from abc import ABCMeta
import six


@six.add_metaclass(ABCMeta)
class BaseWrapper(object):
    """
    Every wrapper needs this asignment, so it's moved to base class
    """

    def __init__(self, tl_config):
        self.tl_config = tl_config


class ListAbstractionsWrapper(BaseWrapper):
    """
    Base class for every wrapper whose object is redirected to some place
    inside a collection in a new model. It provides an operation of finding
    proper index of this object.
    """
    def get_instance(self, wanted_class, dev_list):
        if dev_list is None or len(dev_list) == 0:
            return None

        wanted_instances = list(
            filter(lambda x: isinstance(x, wanted_class), dev_list))

        if len(wanted_instances) == 0:
            return None
        else:
            return wanted_instances[0]
